  for (let d = first; d <= last && d <= T; d = addDays(d, 1)) { const st = dayStatus(id, d); if (['present', 'late', 'wfh', 'half'].includes(st.s) && st.r) { days++; worked += netMins(st.r); brk += breakMins(st.r); if (st.r.out) ot += Math.max(0, hm2m(st.r.out) - hm2m(sh.end)); if (st.s === 'late') late++; } }
