  if (tab === 'lc') { const ev = [[e.joined, '🚀', 'Joined ' + DB.company, e.title]]; rows('promotions').filter(p => p.emp === e.id && p.status === 'Executed').forEach(p => ev.push([p.date, '📈', 'Promoted to ' + p.newTitle, p.type])); rows('awards').filter(a => a.emp === e.id).forEach(a => ev.push([a.date, '🏆', a.type, a.description])); DB.kudos.filter(k => k.to === e.id).forEach(k => ev.push([k.ts, '👏', 'Kudos: ' + k.badge, k.msg])); if (isHR() || own) rows('warnings').filter(w => w.emp === e.id).forEach(w => ev.push([w.date, '⚠', 'Verbal warning', w.title])); if (e.exit) ev.push([e.exit, '👋', 'Last working day', e.status]); ev.sort((a, b) => a[0] < b[0] ? 1 : -1); body = `<div class="card"><div class="timeline">${ev.map(x => `<div class="tli"><span class="dot">${x[1]}</span><div><b>${esc(x[2])}</b><div class="muted small">${fmtDate(x[0])} · ${esc(x[3] || '')}</div></div></div>`).join('')}</div></div>`; }
  if (tab === 'dc') body = dutyCalendarHtml(e);
  if (tab === 'kyc') body = docsPanel(e);
