CHG.photo = el => { const f = el.files[0]; if (!f) return; const img = new Image(), url = URL.createObjectURL(f); img.onload = () => { const c = document.createElement('canvas'); c.width = c.height = 160; const x = c.getContext('2d'), s = Math.min(img.width, img.height); x.drawImage(img, (img.width - s) / 2, (img.height - s) / 2, s, s, 0, 0, 160, 160); me().photo = c.toDataURL('image/jpeg', .8); URL.revokeObjectURL(url); save(); render(); toast('Photo updated'); }; img.onerror = () => toast('Could not read that image', 'err'); img.src = url; };
