ACT.pw_change = () => modal('Change password', `<div class="col">${fld('Current password', 'cur', '', 'password', 'required autocomplete="current-password"')}${fld('New password (8+ characters)', 'n1', '', 'password', 'required minlength="8" autocomplete="new-password"')}${fld('Confirm new password', 'n2', '', 'password', 'required autocomplete="new-password"')}</div>`, d => { if (d.cur !== me().pass) { toast('Current password is incorrect', 'err'); return false; } if (d.n1 !== d.n2) { toast('New passwords do not match', 'err'); return false; } if (d.n1 === d.cur) { toast('Choose a different password', 'err'); return false; } me().pass = d.n1; log('Changed own password'); save(); toast('Password changed'); }, 'Update password');

/* ================= NOTIFICATIONS PAGE ================= */
PAGE_FN.notifications = () => {
  const f = S.noteF || 'all', all = DB.notes.filter(n => n.to === me().id), list = all.filter(n => f === 'all' || (f === 'unread' ? !n.read : n.read)); const unread = all.filter(n => !n.read).length;
  return head('Notifications', `${unread} unread of ${all.length}`, `<button class="btn" data-act="readall2">${ic('check')} Mark all read</button>`) + `<div class="toolbar"><div class="pill-toggle">${[['all', 'All'], ['unread', 'Unread'], ['read', 'Read']].map(([k, l]) => `<button class="${f === k ? 'on' : ''}" data-act="notef" data-v="${k}">${l}</button>`).join('')}</div></div><div class="card pad0 tablewrap"><table><thead><tr><th>Message</th><th>Received</th><th>Seen</th><th></th></tr></thead><tbody>${list.map(n => `<tr class="${n.read ? '' : 'unrow'}"><td>${n.read ? '' : '<span class="live-dot" style="margin-right:8px"></span>'}${esc(n.msg)}</td><td class="nowrap muted small">${new Date(n.ts).toLocaleString('en-IN', { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' })}</td><td class="nowrap small">${n.read ? '<span class="badge ok">Seen ' + new Date(n.seenAt || n.ts).toLocaleTimeString('en-IN', { hour: '2-digit', minute: '2-digit' }) + '</span>' : '<span class="badge warn">New</span>'}</td><td>${n.read ? '' : `<button class="btn sm" data-act="note_seen" data-id="${n.id}">Mark seen</button>`}</td></tr>`).join('') || '<tr><td colspan="4" class="empty">You are all caught up 🎉</td></tr>'}</tbody></table></div>`;
};
ACT.notef = el => { S.noteF = el.dataset.v; render(); };
ACT.note_seen = el => { const n = DB.notes.find(x => x.id === el.dataset.id); n.read = true; n.seenAt = Date.now(); save(); render(); };
ACT.readall2 = () => { DB.notes.forEach(n => { if (n.to === me().id && !n.read) { n.read = true; n.seenAt = Date.now(); } }); save(); render(); };
ACT.readall = ACT.readall2;
const _notes = ACT.notes; ACT.notes = el => { _notes(el); const m = $('#notemenu .pop-menu'); if (m) m.insertAdjacentHTML('beforeend', '<a href="#/notifications" class="it" style="display:block;text-align:center;font-weight:600">View all notifications →</a>'); };

