PAGE_FN.notes = () => {
  const mine = rows('sticky').filter(n => n.emp === me().id), f = S.noteP || '';
  return head('Sticky notes', 'Private reminders, colour-coded by priority', `<button class="btn primary" data-act="note_new">${ic('plus')} New note</button>`) + `<div class="toolbar"><div class="pill-toggle">${['', 'High', 'Medium', 'Low'].map(p => `<button class="${f === p ? 'on' : ''}" data-act="notep" data-v="${p}">${p || 'All'}</button>`).join('')}</div></div><div class="grid" style="grid-template-columns:repeat(auto-fill,minmax(250px,1fr))">${mine.filter(n => !f || n.priority === f).map(n => `<div class="stickyc p-${n.priority}"><div class="row"><b style="flex:1">${esc(n.title || 'Note')}</b><span class="badge">${n.priority}</span></div><p>${esc(n.text)}</p><div class="row"><button class="btn sm" data-act="note_edit" data-id="${n.id}">Edit</button><button class="btn sm danger" data-act="note_del2" data-id="${n.id}">Delete</button></div></div>`).join('') || '<div class="card empty" style="grid-column:1/-1">No notes yet.</div>'}</div>`;
};
ACT.notep = el => { S.noteP = el.dataset.v; render(); };
const noteForm = n => `<div class="col">${fld('Title', 'title', n?.title || '')}${sel('Priority', 'priority', ['Low', 'Medium', 'High'].map(x => [x, x]), n?.priority || 'Medium')}<label class="f">Note<textarea class="input" name="text" rows="3" required>${esc(n?.text || '')}</textarea></label></div>`;
ACT.note_new = () => modal('New sticky note', noteForm(), d => { rows('sticky').unshift({ id: uid('s'), emp: me().id, ...d }); save(); render(); toast('Note saved'); }, 'Save');
ACT.note_edit = el => { const n = rows('sticky').find(x => x.id === el.dataset.id); modal('Edit note', noteForm(n), d => { Object.assign(n, d); save(); render(); }, 'Save'); };
ACT.note_del2 = el => confirmBox('Delete this note?', () => { DB.ent.sticky = rows('sticky').filter(n => n.id !== el.dataset.id); save(); render(); });
ACT.note_del = ACT.note_del2;

/* ================= LEAVE APPLY (substitute + attachment + summary) ================= */
const readFile = (input, max = 400000) => new Promise(res => { const f = input?.files?.[0]; if (!f) return res(null); if (f.size > max) { toast(`File is too large (max ${Math.round(max / 1000)} KB)`, 'err'); return res(null); } const r = new FileReader(); r.onload = () => res({ name: f.name, data: r.result }); r.readAsDataURL(f); });
ACT.leave_new = () => {
  const u = me(), peers = activeEmps().filter(e => e.id !== u.id && (e.dept === u.dept || e.mgr === u.mgr));
  const m = modal('Apply for leave', `<div class="grid g-main" style="gap:20px;grid-template-columns:1.6fr 1fr"><div class="form-grid">${sel('Leave type', 'type', Object.entries(LEAVE_TYPES), 'CL', 'full')}${sel('Substitute (covers your work)', 'sub', [['', '— none —'], ...peers.map(e => [e.id, e.name])], '', 'full')}${fld('From', 'from', TODAY(), 'date', 'required')}${fld('To', 'to', TODAY(), 'date', 'required')}<div class="full" id="lvinfo"></div><label class="f full">Attachment <span class="h">(medical certificate, optional)</span><input class="input" type="file" name="file" accept="image/*,.pdf"></label><label class="f full">Reason<textarea class="input" name="reason" rows="2" required></textarea></label></div><div><div class="card flat tc"><div class="muted small">Leave summary</div>${ringHtml(0, '…', 'balance', 'var(--accent)').replace('class="ring"', 'class="ring" id="lvring" style="margin:8px auto"')}<div id="lvsum" class="small"></div></div></div></div>`, async (d, mm) => {
    if (d.to < d.from) { toast('End date is before start date', 'err'); return false; } const days = leaveDays(d.from, d.to, u.id); if (!days) { toast('Selected dates are all weekends/holidays', 'err'); return false; }
    const b = leaveBalance(u.id, d.type); if (days > b.left) { toast(`Only ${b.left} day(s) of ${LEAVE_TYPES[d.type]} left`, 'err'); return false; }
    if (DB.leaves.some(l => l.emp === u.id && ['Pending', 'Approved'].includes(l.status) && d.from <= l.to && d.to >= l.from)) { toast('You already have leave on those dates', 'err'); return false; }
    const file = await readFile($('[name=file]', mm)), ap = u.mgr || 'E001'; DB.leaves.unshift({ id: uid('L'), emp: u.id, type: d.type, from: d.from, to: d.to, days, status: 'Pending', reason: d.reason, ts: TODAY(), approver: ap, sub: d.sub || '', file: file?.name || '' });
    notify(ap, `${u.name} applied for ${days} day(s) of ${LEAVE_TYPES[d.type]}`); if (d.sub) notify(d.sub, `${u.name} named you as substitute from ${fmtShort(d.from)} to ${fmtShort(d.to)}`); log('Applied leave'); save(); render(); toast('Leave request sent to ' + emp(ap).name); return true;
  }, 'Submit request', true);
  const upd = () => { const f = $('[name=from]', m).value, t = $('[name=to]', m).value, ty = $('[name=type]', m).value, b = leaveBalance(u.id, ty), n = f && t && t >= f ? leaveDays(f, t, u.id) : 0; $('#lvinfo', m).innerHTML = n ? `<span class="badge acc">${n} working day(s)</span> <span class="muted small">${b.left === Infinity ? 'Unpaid — no limit' : 'Balance after: ' + (b.left - n)}</span>` : ''; const tot = b.quota === Infinity ? 0 : b.quota; $('#lvsum', m).innerHTML = b.quota === Infinity ? 'Unpaid leave has no quota.' : `<b>${b.left}</b> of ${tot} days left<br><span class="muted">${b.used} used · ${b.pending} pending</span>`; const pg = $('#lvring .pg', m), mid = $('#lvring .mid b', m); if (pg) { const C = 2 * Math.PI * 56; pg.style.animation = 'none'; pg.style.strokeDasharray = C; pg.style.strokeDashoffset = C * (1 - (tot ? Math.max(0, b.left - n) / tot : 0)); } if (mid) mid.textContent = tot ? Math.max(0, b.left - n) : '∞'; };
  m.addEventListener('input', upd); m.addEventListener('change', upd); upd();
};

/* ================= EXPENSE CLAIM (title, payment method, receipt) ================= */
ACT.claim_new = () => modal('New expense claim', `<div class="form-grid">${fld('Claim title', 'title', '', 'text', 'required', 'full')}${sel('Category', 'cat', ['Travel', 'Fuel', 'Site expenses', 'Client entertainment', 'Meals', 'Internet', 'Equipment', 'Training', 'Other'].map(x => [x, x]))}${fld('Amount (₹)', 'amount', '', 'number', 'min="1" step="any" required')}${fld('Claim date', 'date', TODAY(), 'date', `max="${TODAY()}" required`)}${sel('Payment method', 'pay', ['Bank transfer', 'Cash', 'Add to next payroll'].map(x => [x, x]))}<label class="f full">Receipt / attachment <span class="h">(image or PDF, up to 400 KB)</span><input class="input" type="file" name="file" accept="image/*,.pdf"></label><label class="f full">Description<textarea class="input" name="desc" rows="2" required></textarea></label></div>`, async (d, mm) => { const file = await readFile($('[name=file]', mm)); DB.claims.unshift({ id: uid('X'), emp: me().id, title: d.title, cat: d.cat, amount: +d.amount, date: d.date, pay: d.pay, desc: d.desc, file: file?.name || '', receipt: file?.data || '', status: 'Pending' }); notify(me().mgr || 'E002', `${me().name} submitted an expense claim: ${d.title}`); save(); render(); toast('Claim submitted'); return true; }, 'Submit');

